using MediatR;using Microsoft.AspNetCore.Mvc;using RevenuUsage.Application.Features.Reporting;namespace RevenuUsage.API.Controllers;[ApiController][Route("api/[controller]")]public sealed class ReportsController:ControllerBase{private readonly IMediator _m;public ReportsController(IMediator m)=>_m=m;[HttpGet("dashboard")]public async Task<ActionResult>Dashboard(DateTime? asOfDate,CancellationToken ct)=>Ok(await _m.Send(new GetDashboardQuery(asOfDate??DateTime.Today),ct));[HttpGet("foreign-reserve")]public async Task<ActionResult>Reserve(DateTime startDate,DateTime endDate,CancellationToken ct)=>Ok(await _m.Send(new GetForeignReserveReportQuery(startDate,endDate),ct));[HttpGet("obligations")]public async Task<ActionResult>Obligations(DateTime? startDate,DateTime? endDate,string? status,CancellationToken ct)=>Ok(await _m.Send(new GetObligationReportQuery(startDate,endDate,status),ct));}
